const FEE0 = [['ADM001', 24000, 24000], ['ADM002', 28000, 28000], ['ADM003', 26000, 13000], ['ADM004', 22000, 0], ['ADM005', 26000, 26000], ['ADM006', 30000, 15000], ['ADM007', 24000, 0], ['ADM008', 20000, 20000]];
function feeOf(s, i) { const base = FEE0.find(x => x[0] === s.adm); const tot = base ? base[1] : 20000 + (hashStr(s.adm) % 6) * 2000; const paid0 = base ? base[2] : (hashStr(s.adm) % 7 === 0 ? 0 : hashStr(s.adm) % 5 === 0 ? tot / 2 : tot); const paid = Math.min(tot, paid0 + (A().fees[s.adm] || 0)); return { tot, paid, due: tot - paid, st: paid >= tot ? 'Paid' : paid > 0 ? 'Partially Paid' : 'Pending' }; }
