DDS.collectmenu = () => `<button class="dd-i" data-act="collectpay">${ic('card', 15)}Collect from student</button><button class="dd-i" data-act="geninvoice">${ic('file', 15)}Generate invoice</button><button class="dd-i" data-act="toast" data-msg="Payment reminders sent to 145 parents">${ic('bell', 15)}Send reminders</button>`;
