ACT.collectpay = d => {
  const id = d.id || 'ADM004'; const s = allStudents().find(x => x.adm === id); const fee = feeOf(s);
  openModal('Collect Payment', `<div class="g" style="grid-template-columns:1fr 1fr">${field('Student', `<div class="sel" style="width:100%"><select name="adm" id="cpst">${allStudents().slice(0, 40).map((x, i) => { const fe = feeOf(x, i); return `<option value="${x.adm}" ${x.adm === id ? 'selected' : ''}>${x.name} (${x.adm}) - due ${inr(fe.due)}</option>`; }).join('')}</select>${ic('down', 15)}</div>`, 1)}${field('Amount (₹)', `<input class="inp" type="number" name="amt" value="${fee.due || 0}"/>`, 1)}${field('Payment Mode', `<div class="sel" style="width:100%"><select name="mode"><option>UPI</option><option>Cash</option><option>Card</option><option>Bank Transfer</option><option>Cheque</option></select>${ic('down', 15)}</div>`)}${field('Reference No.', '<input class="inp" name="ref" placeholder="UPI / cheque reference"/>')}</div>`, `<button class="btn btn-outline" data-act="mclose">Cancel</button><button class="btn btn-primary" data-act="collectpay2">${ic('checkc', 15)}Record Payment</button>`);
};
ACT.collectpay2 = () => { const f = formVals(document.querySelector('.modal')); const amt = Number(f.amt); if (!amt || amt <= 0) { toast('Enter an amount', 'warn'); return; } const s = allStudents().find(x => x.adm === f.adm); const fee = feeOf(s); if (amt > fee.due) { toast(`Amount exceeds due (${inr(fee.due)})`, 'err'); return; } A().fees[f.adm] = (A().fees[f.adm] || 0) + amt; A().txns = [['26 Sep 2026', `Fee Payment - ${s.name}`, 'Income', amt], ...(A().txns || [])]; save(); audit('Fee collected', `${inr(amt)} from ${s.name} via ${f.mode}`); closeModal(); toast(`${inr(amt)} received from ${s.name}. Receipt sent.`); refresh(); };
