ACT.addfuel = () => openModal('Add Fuel Entry', `<div class="g" style="grid-template-columns:1fr 1fr">${field('Vehicle', `<div class="sel" style="width:100%"><select>${DATA.vehicles.slice(0, 10).map(v => `<option>${v.no}</option>`).join('')}</select>${ic('down', 15)}</div>`)}${field('Litres', '<input class="inp" type="number" name="l" value="28"/>')}${field('Amount (₹)', '<input class="inp" type="number" name="amt" value="2800"/>', 1)}${field('Odometer', '<input class="inp" value="1,24,560"/>')}</div><input type="hidden" name="cat" value="Fuel"/><input type="hidden" name="desc" value="Fuel entry"/>`, `<button class="btn btn-outline" data-act="mclose">Cancel</button><button class="btn btn-primary" data-act="recexpense2">Save Entry</button>`);
ACT.vendorpay = () => openModal('Make Vendor Payment', `${field('Vendor', `<div class="sel" style="width:100%"><select name="desc">${['ABC Travels', 'ABC Auto Service', 'Shree Motors Workshop', 'MotorCare Pvt Ltd'].map(v => `<option>${v}</option>`).join('')}</select>${ic('down', 15)}</div>`)}${field('Amount (₹)', '<input class="inp" type="number" name="amt" value="44000"/>', 1)}<input type="hidden" name="cat" value="Vendor"/>`, `<button class="btn btn-outline" data-act="mclose">Cancel</button><button class="btn btn-primary" data-act="recexpense2">Pay Vendor</button>`);
ACT.recexpense2 = () => { const f = formVals(document.querySelector('.modal')); const amt = Number(f.amt); if (!amt) { toast('Enter an amount', 'warn'); return; } A().txns = [['26 Sep 2026', `${f.cat === 'Vendor' ? 'Vendor Payment - ' : f.cat + ' - '}${f.desc || f.cat}`, 'Expense', -amt], ...(A().txns || [])]; save(); audit('Expense recorded', `${f.cat} ${inr(amt)}`); closeModal(); toast('Expense recorded'); refresh(); };
ACT.genreport = () => openModal('Generate Report', `${field('Report', `<div class="sel" style="width:100%"><select><option>Income & Expense Statement</option><option>Fee Collection Summary</option><option>Outstanding Dues</option><option>Vendor Ledger</option></select>${ic('down', 15)}</div>`)}${field('Format', '<div class="row" style="gap:16px"><label class="row"><input type="radio" name="fmt" checked/> PDF</label><label class="row"><input type="radio" name="fmt"/> Excel</label></div>')}`, `<button class="btn btn-outline" data-act="mclose">Cancel</button><button class="btn btn-primary" data-act="genreport2">${ic('download', 15)}Generate</button>`);
ACT.genreport2 = () => { closeModal(); toast('Report generated and downloaded'); };
ACT.alltxn = () => openModal('All Transactions', `<table class="tbl mt12"><thead><tr><th>Date</th><th>Description</th><th>Type</th><th class="tr">Amount</th></tr></thead><tbody>${[...(A().txns || []), ...TXNS0].map(t => `<tr><td>${t[0]}</td><td>${esc(t[1])}</td><td>${t[2]}</td><td class="tr b ${t[3] > 0 ? 'c-green' : 'c-red'}">${t[3] > 0 ? '+' : '-'}${inr(Math.abs(t[3]))}</td></tr>`).join('')}</tbody></table>`, '', 'lg');

/* ---------------- Safety ---------------- */
page('admin/safety', {
  title: 'Safety', render: () => {
    const inc = A().incidents, sos = A().sos, live = UI.slive !== false;
    const typeCls = t => ({ 'Near Miss': 'orange', 'Minor Injury': 'red', 'SOS Alert': 'red', Harassment: 'red', Medical: 'orange' }[t] || 'red');
    const sdonut = (title, center, cl, segs, rows) => `<div class="card">${cardH(title, viewAll('#/admin/safety'))}<div class="card-b row" style="gap:14px">${donut(segs, 118, 16, `<div class="v fs18">${center}</div><div class="l">${cl}</div>`)}<div class="lg" style="flex:1">${rows.map(x => `<div class="lg-r"><span class="sqc" style="background:${x[0]}"></span><span style="flex:1">${x[1]}</span><b>${x[2]}</b></div>`).join('')}</div></div></div>`;
    const open = inc.filter(i => i.status === 'Open').length;
    return `<div class="ph"><div><h1>Safety</h1><p>Ensure safe, secure and compliant school transport operations for all students.</p></div><div class="ph-act"><button class="datebtn" data-act="dd" data-dd="date" data-w="220">${ic('cal', 17)}${UI.date || 'Thu, 26 Sep 2026'}${ic('down', 15)}<span style="border-left:1px solid var(--line);height:22px"></span>${ic('down', 15)}</button></div></div>
    <div class="kpis" style="grid-template-columns:repeat(6,1fr)">${kpi({ c: 'red', i: 'shieldalert', v: String(7 + inc.length), l: 'Incidents', f: `<span class="c-red">3 Critical</span>${fsep}<span class="c-red">${open + 3} Open</span>` })}${kpi({ c: 'orange', iconHtml: '<b style="font-size:13px">SOS</b>', v: String(3 + sos.length - (sos.filter(s => s.status === 'Resolved').length ? 1 : 0)), l: 'SOS Alerts', f: `${sos.filter(s => s.status === 'Active').length} Active ${fsep} ${3 + sos.filter(s => s.status === 'Resolved').length} Resolved` })}${kpi({ c: 'purple', i: 'users', v: '1,245', l: 'Students Safe', f: '<span class="c-green">100% Tracked</span>' })}${kpi({ c: 'green', i: 'busf', v: '1,230', l: 'Boarding Verified', f: '<span class="c-green">15 Pending</span>' })}${kpi({ c: 'blue', i: 'user', v: '48', l: 'Driver Compliant', f: '<span class="c-red">2 Non-Compliant</span>' })}${kpi({ c: 'orange', i: 'busf', v: '50', l: 'Vehicle Compliant', f: '<span class="c-red">3 Due for Inspection</span>' })}</div>
    <div class="g rgrid" style="grid-template-columns:minmax(0,1fr) minmax(0,1.15fr) minmax(0,.75fr);margin-bottom:12px">
      <div class="card">${cardH('Live Safety Map', `<label class="row fs12" style="margin-left:auto;gap:6px;cursor:pointer"><span data-act="set" data-k="u:slive" data-v="${!live}" style="width:30px;height:17px;border-radius:99px;background:${live ? '#1463ff' : '#cbd5e1'};position:relative;display:inline-block"><span style="position:absolute;top:2px;${live ? 'right:2px' : 'left:2px'};width:13px;height:13px;border-radius:50%;background:#fff"></span></span>Live Vehicles</label>`)}<div class="card-b"><div class="map" style="height:226px">${mapSVG({ w: 460, h: 226, seed: 301, routes: [{ pts: [[20, 170], [80, 150], [110, 130], [150, 110], [180, 90]], c: '#f97316', w: 3.5 }, { pts: [[180, 90], [240, 82], [255, 76], [300, 50]], c: '#16a34a', w: 3.5 }, { pts: [[110, 130], [130, 60], [150, 40]], c: '#ef4444', w: 3.5 }], markers: live ? [{ t: 'pin', x: 120, y: 58, c: '#ef4444', icon: 'warn' }, { t: 'call', x: 136, y: 18, lines: [['SOS Alert', 700, 11.5, '#dc2626'], ['R-05 | 07:32 AM', 500, 10.5]] }, { t: 'pin', x: 110, y: 130, c: '#f97316', icon: 'warn' }, { t: 'call', x: 126, y: 128, lines: [['Speed Alert', 700, 11.5, '#ea580c'], ['R-03 | 08:10 AM', 500, 10.5]] }, { t: 'pin', x: 280, y: 92, c: '#16a34a', icon: 'home' }, { t: 'call', x: 296, y: 92, lines: [['Normal', 700, 11.5, '#16a34a'], ['R-01 | On Time', 500, 10.5]] }, { t: 'pin', x: 280, y: 128, c: '#16a34a', icon: 'home' }, { t: 'pin', x: 60, y: 160, c: '#16a34a', icon: 'home' }, { t: 'pin', x: 300, y: 54, c: '#2563eb', icon: 'home' }, { t: 'call', x: 314, y: 38, lines: [['City Plus School', 700, 11]] }] : [{ t: 'pin', x: 300, y: 54, c: '#2563eb', icon: 'home' }] })}<div class="map-ctl" style="top:8px"><button data-act="liveview">${ic('fullscreen', 15)}</button></div><div class="map-ctl" style="bottom:8px"><button data-act="toast" data-msg="Zoomed in">${ic('plus', 14)}</button><button data-act="toast" data-msg="Zoomed out">${ic('minus', 14)}</button><button data-act="toast" data-msg="Centered">${ic('locate', 14)}</button></div></div></div></div>
      <div class="card">${cardH('Recent Incidents', viewAll('reportinc', 'View All'))}<table class="tbl compact"><thead><tr><th>Time</th><th>Type</th><th>Description</th><th>Route</th><th>Status</th><th>Actions</th></tr></thead><tbody>${inc.slice(0, 5).map((x, i) => `<tr><td class="fs12 nowrap">${x.time}</td><td><span class="bd bd-${typeCls(x.type)}" style="border-radius:4px">${x.type}</span></td><td class="fs12">${esc(x.desc)}</td><td class="c-blue fs12">${x.route}</td><td>${x.status === 'Open' ? '<span class="bd bd-red">Open</span>' : x.status === 'In Progress' ? '<span class="bd bd-orange">In Progress</span>' : '<span class="bd bd-green">Resolved</span>'}</td><td><button class="ibtn" data-act="dd" data-dd="incrow" data-i="${i}" data-w="190">${ic('more', 15)}</button></td></tr>`).join('')}</tbody></table></div>
      <div class="card">${cardH('Active SOS Alerts', viewAll('#/admin/safety?s=sos'))}<div class="card-b">${sos.map((x, i) => `<div class="row" style="padding:10px 0;border-bottom:1px solid var(--line-2);align-items:flex-start">${av(x.name, 46, 'kid-' + (x.name.startsWith('Diya') ? 'f' : 'm'))}<div style="flex:1"><div class="b fs13">${x.name}</div><div class="fs12 mut">${x.cls}</div><div class="fs12 mut">${x.route}</div></div><div class="tr"><span class="bd ${x.status === 'Active' ? 'bd-red' : x.status === 'Resolved' ? 'bd-green' : 'bd-orange'} dot">${x.status}</span><div class="fs12 mut mt8">${x.time}</div></div><button class="btn ${x.status === 'Active' ? 'btn-danger' : 'btn-primary'} btn-sm" style="margin-left:8px;align-self:center" data-act="soscall" data-i="${i}">${ic('phone', 14)}Call</button></div>`).join('')}</div></div></div>
    <div class="g rgrid" style="grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:12px">${sdonut('Student Safety', '1,245', 'Total Students', [{ v: 1180, c: '#16a34a' }, { v: 42, c: '#2563eb' }, { v: 15, c: '#f97316' }, { v: 8, c: '#ef4444' }], [['#16a34a', 'On Board', '1,180 (95%)'], ['#2563eb', 'At Stop', '42 (3%)'], ['#f97316', 'Not Boarded', '15 (1%)'], ['#ef4444', 'Safety Alert', '8 (1%)']])}${sdonut('Boarding Verification', '1,245', 'Total Trips', [{ v: 1230, c: '#16a34a' }, { v: 15, c: '#f97316' }, { v: 5, c: '#ef4444' }], [['#16a34a', 'Verified', '1,230 (98%)'], ['#f97316', 'Pending', '15 (1%)'], ['#ef4444', 'Missed', '5 (0.5%)']])}${sdonut('Driver Compliance', '48', 'Total Drivers', [{ v: 46, c: '#16a34a' }, { v: 2, c: '#ef4444' }], [['#16a34a', 'Compliant', '46 (96%)'], ['#ef4444', 'Non-Compliant', '2 (4%)']])}${sdonut('Vehicle Compliance', '50', 'Total Vehicles', [{ v: 47, c: '#16a34a' }, { v: 3, c: '#f97316' }], [['#16a34a', 'Compliant', '47 (94%)'], ['#f97316', 'Due for Inspection', '3 (6%)'], ['#ef4444', 'Non-Compliant', '0 (0%)']])}</div>
    <div class="g rgrid" style="grid-template-columns:minmax(0,1fr) minmax(0,1.25fr)">
      <div class="card">${cardH('Safety Inspections', viewAll('#/admin/maintenance?s=inspections'))}<table class="tbl compact"><thead><tr><th>Date</th><th>Vehicle</th><th>Type</th><th>Inspector</th><th>Status</th><th>Next Due</th><th>Actions</th></tr></thead><tbody>${[['22 Sep 2026', 'GJ01AB1234', 'Pre-Trip', 'S. Kumar', 'Pass', '29 Sep 2026'], ['21 Sep 2026', 'GJ01CD5678', 'Monthly', 'A. Mehta', 'Pass', '21 Oct 2026'], ['20 Sep 2026', 'GJ01EF9012', 'Pre-Trip', 'R. Patel', 'Fail', '24 Sep 2026'], ['19 Sep 2026', 'GJ01GH3456', 'Quarterly', 'P. Yadav', 'Pass', '19 Dec 2026']].map(r => `<tr><td class="fs12">${r[0]}</td><td class="t1 fs12">${r[1]}</td><td class="fs12">${r[2]}</td><td class="fs12">${r[3]}</td><td>${badge(r[4])}</td><td class="fs12 ${r[4] === 'Fail' ? 'c-red' : ''}">${r[5]}</td><td><button class="ibtn" data-act="toast" data-msg="Inspection report for ${r[1]} opened">${ic('more', 15)}</button></td></tr>`).join('')}</tbody></table></div>
      <div class="card">${cardH('Emergency Records', viewAll('reportinc', 'View All'))}<table class="tbl compact"><thead><tr><th>Date & Time</th><th>Type</th><th>Student/Route</th><th>Details</th><th>Handled By</th><th>Status</th><th>Actions</th></tr></thead><tbody>${[['07:32 AM', 'SOS Alert', 'Diya Patel (R-05)', 'SOS pressed during trip', 'Coordinator', 'Resolved'], ['08:45 AM', 'Medical', 'Rohan Desai (R-02)', 'Felt unwell, taken to clinic', 'Driver', 'Resolved'], ['06:55 AM', 'Harassment', 'R-04', 'Misbehavior reported', 'Admin', 'Open'], ['05:20 PM', 'Accident', 'Vehicle GJ01EF9012', 'Minor collision, no injury', 'Maintenance', 'Closed']].map(r => `<tr><td class="fs12">${r[0]}</td><td><span class="bd bd-red" style="border-radius:4px">${r[1]}</span></td><td class="fs12">${r[2]}</td><td class="fs12">${r[3]}</td><td class="fs12">${r[4]}</td><td>${badge(r[5])}</td><td><button class="ibtn" data-act="toast" data-msg="Record opened">${ic('more', 15)}</button></td></tr>`).join('')}</tbody></table></div></div>`;
  },
});
DDS.incrow = d => `<button class="dd-i" data-act="incstatus" data-i="${d.i}" data-s="In Progress">${ic('clock', 15)}Mark In Progress</button><button class="dd-i" data-act="incstatus" data-i="${d.i}" data-s="Resolved">${ic('checkc', 15)}Mark Resolved</button><button class="dd-i" data-act="toast" data-msg="Escalated to Safety Officer" data-tt="warn">${ic('arrowu', 15)}Escalate</button>`;
ACT.incstatus = d => { const x = A().incidents[d.i]; x.status = d.s; save(); audit('Incident updated', `${x.type} ${d.s}`); toast(`Incident marked ${d.s}`); refresh(); };
ACT.soscall = d => { const x = A().sos[d.i]; toast(`Calling parent of ${x.name}...`); if (x.status === 'Active') { x.status = 'Acknowledged'; save(); refresh(); } else if (x.status === 'Acknowledged') { x.status = 'Resolved'; save(); refresh(); } };
ACT.reportinc = () => openModal('Report Incident', `<div class="g" style="grid-template-columns:1fr 1fr">${field('Type', `<div class="sel" style="width:100%"><select name="type">${['Near Miss', 'Minor Injury', 'Medical', 'Harassment', 'SOS Alert', 'Accident'].map(t => `<option>${t}</option>`).join('')}</select>${ic('down', 15)}</div>`)}${field('Route', `<div class="sel" style="width:100%"><select name="route">${DATA.routes.slice(0, 10).map(r => `<option>${r.code}</option>`).join('')}</select>${ic('down', 15)}</div>`)}</div>${field('Description', '<textarea class="inp" name="desc" placeholder="What happened?"></textarea>', 1)}<div class="sec-t mt16">All Incidents</div><table class="tbl compact"><tbody>${A().incidents.map(x => `<tr><td>${x.time}</td><td>${x.type}</td><td>${esc(x.desc)}</td><td>${badge(x.status)}</td></tr>`).join('')}</tbody></table>`, `<button class="btn btn-outline" data-act="mclose">Close</button><button class="btn btn-primary" data-act="reportinc2">Log Incident</button>`, 'lg');
ACT.reportinc2 = () => { const f = formVals(document.querySelector('.modal')); if (!f.desc) { toast('Describe the incident', 'warn'); return; } A().incidents.unshift({ time: nowTime(), type: f.type, desc: f.desc, route: f.route, status: 'Open' }); save(); audit('Incident logged', `${f.type} on ${f.route}`); closeModal(); toast('Incident logged and safety officer notified'); refresh(); };

/* ---------------- Sustainability ---------------- */
page('admin/sustainability', {
  title: 'Sustainability', render: () => {
    const f = ui('sus', { m: 'September 2026', tr: 'Last 12 Months' });
    const kp = (c, i, v, l, ft) => kpi({ c, i, v, l, f: ft });
    return `<div class="ph"><div><h1>Sustainability</h1><p>Track fuel consumption, CO₂ emissions and environmental impact of your school transport operations.</p></div><div class="ph-act"><div class="sel">${ic('cal', 16, 'style="left:12px;right:auto"')}<select data-bind="u:sus.m" style="padding-left:38px;height:40px;width:200px">${['September 2026', 'August 2026', 'July 2026'].map(m => `<option ${f.m === m ? 'selected' : ''}>${m}</option>`).join('')}</select>${ic('down', 15)}</div></div></div>
    <div class="kpis" style="grid-template-columns:repeat(6,1fr)">${kp('green', 'fuel', '8,420 L', 'Total Fuel Consumed', trend(false, '12%', true))}${kp('blue', 'leaf', '22.6 t CO₂', 'Total Emissions (All Scopes)', trend(false, '15%', true))}${kp('red', 'truck', '18.4 t CO₂', 'Scope 1 (Direct - Fleet)', '81% of total')}${kp('orange', 'zap', '1.2 t CO₂', 'Scope 2 (Electricity)', '5% of total')}${kp('purple', 'users', '3.0 t CO₂', 'Scope 3 (Vendors/Other)', '14% of total')}${kp('green', 'leaf', '17.8 kg', 'CO₂ per Student', trend(false, '18%', true))}</div>
    <div class="g rgrid" style="grid-template-columns:minmax(0,1.45fr) minmax(0,1fr) minmax(0,1.05fr);margin-bottom:12px">
      <div class="card">${cardH('Fuel Consumption & CO₂ Emissions Trend', `<span style="margin-left:auto">${sel('u:sus.tr', ['Last 12 Months', 'Last 6 Months'], f.tr, 'data-norefresh')}</span>`)}<div class="card-b">${bars({ w: 560, h: 170, labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Jul', 'Aug', 'Sep'], series: [{ v: [1350, 1450, 1360, 1620, 1250, 1380, 1340, 1240, 1320, 1240], c: '#16a34a' }], ticks: [0, 500, 1000, 1500, 2000], fmt: v => num(v), line: { v: [33, 32, 30, 28, 24, 29, 31, 29, 30, 27], c: '#1463ff', ticks: [0, 10, 20, 30, 40] }, yl: 'Fuel (Liters)', yr: 'CO₂ Emissions (t)', bw: .5 })}<div class="row fs12" style="justify-content:center;gap:18px"><span class="row" style="gap:6px"><span class="sqc" style="background:#16a34a"></span>Fuel Consumption (L)</span><span class="row" style="gap:6px"><span style="width:18px;height:2px;background:#1463ff;display:inline-block"></span><span class="dotc" style="background:#fff;border:2px solid #1463ff;margin-left:-13px"></span>CO₂ Emissions (t)</span></div></div></div>
      <div class="card">${cardH('Emissions by Scope (This Month)')}<div class="card-b row" style="gap:16px">${donut([{ v: 81, c: '#ef4444' }, { v: 5, c: '#facc15' }, { v: 14, c: '#8b5cf6' }], 150, 26, '<div class="v">22.6 t</div><div class="l">Total CO₂</div>')}<div class="lg" style="flex:1;gap:12px">${[['#ef4444', 'Scope 1 - Fleet (Direct)', '18.4 t (81%)'], ['#facc15', 'Scope 2 - Electricity', '1.2 t (5%)'], ['#8b5cf6', 'Scope 3 - Vendors/Other', '3.0 t (14%)']].map(x => `<div><div class="row fs13" style="gap:8px"><span class="sqc" style="background:${x[0]}"></span>${x[1]}</div><div class="b fs13" style="padding-left:18px;margin-top:3px">${x[2]}</div></div>`).join('')}</div></div></div>
      <div class="card">${cardH('Emissions by Source')}<div class="card-b">${[['Vehicle Operations', 81, '#16a34a', '18.4 t'], ['Vendor Transport', 9, '#1463ff', '2.1 t'], ['Electricity (Depots)', 5, '#facc15', '1.2 t'], ['Maintenance & Services', 3, '#8b5cf6', '0.6 t'], ['Other (Waste, Admin)', 2, '#64748b', '0.3 t']].map(x => `<div class="row fs12" style="padding:9px 0"><span style="width:130px">${x[0]}</span><div class="hb" style="flex:1"><i style="width:${x[1]}%;background:${x[2]}"></i></div><b style="width:44px" class="tr">${x[3]}</b><span style="width:36px" class="tr mut">${x[1]}%</span></div>`).join('')}</div></div></div>
    <div class="g rgrid" style="grid-template-columns:minmax(0,1.25fr) minmax(0,1.05fr) minmax(0,1fr);margin-bottom:12px">
      <div class="card">${cardH('Vehicle Emissions (Top 5)', viewAll('#/admin/fleet'))}<table class="tbl compact nw"><thead><tr><th>#</th><th>Vehicle No.</th><th>Model</th><th>Fuel Type</th><th>Fuel (L)</th><th>CO₂ (t)</th><th>CO₂ per km (g)</th><th>Status</th><th></th></tr></thead><tbody>${[['GJ01AB1234', 'Tata Starbus', 'Diesel', '1,250', '3.28', 785, 'Normal'], ['GJ01CD5678', 'Ashok Leyland', 'Diesel', '980', '2.57', 762, 'Normal'], ['GJ01EF9012', 'Tata Ultra', 'Diesel', '910', '2.39', 748, 'Normal'], ['GJ01GH3456', 'Mahindra', 'CNG', '620', '1.02', 420, 'Efficient'], ['GJ01IJ7890', 'Eicher', 'Diesel', '540', '1.42', 801, 'Normal']].map((r, i) => `<tr><td>${i + 1}</td><td class="t1">${r[0]}</td><td>${r[1]}</td><td class="${r[2] === 'CNG' ? 'c-green' : ''}" style="text-decoration:underline dotted">${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td>${r[5]}</td><td>${badge(r[6], false)}</td><td><button class="ibtn" data-go="#/admin/fleet?v=${r[0]}">${ic('more', 14)}</button></td></tr>`).join('')}</tbody></table></div>
      <div class="card">${cardH('Route Emissions (Top 5)', viewAll('#/admin/routes'))}<table class="tbl compact nw"><thead><tr><th>#</th><th>Route</th><th>Distance (km)</th><th>CO₂ (kg)</th><th>CO₂ per km (g)</th></tr></thead><tbody>${[['R-01', 'North Zone', 125, 310, '2,480'], ['R-03', 'East Zone', 118, 295, '2,500'], ['R-02', 'South Zone', 102, 260, '2,550'], ['R-05', 'Central Zone', 98, 240, '2,449'], ['R-04', 'West Zone', 95, 220, '2,316']].map((r, i) => `<tr class="clk" data-go="#/admin/routes?r=${r[0]}"><td>${i + 1}</td><td><b>${r[0]}</b> <span class="c-blue" style="text-decoration:underline">${r[1]}</span></td><td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td></tr>`).join('')}</tbody></table></div>
      <div class="card">${cardH('Student Emissions', viewAll('#/admin/students'))}<div class="card-b">${bars({ w: 340, h: 170, labels: ['Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep'], series: [{ v: [28, 26, 24, 22, 20, 18], c: '#1463ff' }], ticks: [0, 10, 20, 30, 40], showVals: true, yl: 'CO₂ per Student (kg)', bw: .62 })}</div></div></div>
    <div class="g rgrid" style="grid-template-columns:minmax(0,2.1fr) minmax(0,1fr)">
      <div class="card">${cardH('Sustainability Reports')}<div class="card-b g" style="grid-template-columns:repeat(5,1fr);gap:10px">${[['barsc', '#16a34a', 'Monthly Emissions Report', 'Fuel, CO₂, Scope 1/2/3'], ['file', '#2563eb', 'Annual Sustainability Report', 'Complete environmental impact'], ['car', '#7c3aed', 'Fleet Comparison Report', 'Vehicle-wise emissions analysis'], ['pin', '#f59e0b', 'Route Efficiency Report', 'Route-wise fuel & CO₂ analysis'], ['users', '#ef4444', 'Student Emissions Report', 'Per student carbon footprint']].map(x => `<div class="sbox" style="display:flex;flex-direction:column;gap:8px"><div class="row" style="align-items:flex-start">${tile(x[0], x[1], x[1] + '18', 44, 24, 10)}<div><div class="b fs12">${x[2]}</div><div class="fs11 mut">${x[3]}</div></div></div><button class="btn btn-primary btn-sm btn-block mt8" data-act="susreport" data-n="${x[2]}">Generate Report</button></div>`).join('')}</div></div>
      <div class="card">${cardH('Quick Actions')}<div class="card-b g" style="grid-template-columns:repeat(3,1fr);gap:8px">${[['leaf', '#16a34a', 'Log Fuel Consumption', 'addfuel'], ['zap', '#f59e0b', 'Log Electricity Usage', 'logelec'], ['truck', '#ef4444', 'Add Vendor Transport', 'vendorpay'], ['calc', '#2563eb', 'Calculate Emissions', 'calcem'], ['file', '#2563eb', 'View Reports', 'susreport'], ['target', '#ef4444', 'Set Reduction Target', 'settarget']].map(x => `<button class="mini" style="text-align:left;padding:10px;gap:8px" data-act="${x[3]}" data-n="Monthly Emissions Report">${ic(x[0], 22, `style="color:${x[1]}"`)}<span class="fs12 m5">${x[2]}</span></button>`).join('')}</div></div></div>`;
  },
});
ACT.susreport = d => { toast(`Generating ${d.n || 'report'}...`); setTimeout(() => toast(`${d.n || 'Report'} ready and downloaded`), 900); };
ACT.logelec = () => openModal('Log Electricity Usage', `${field('Depot', `<div class="sel" style="width:100%"><select><option>Main Depot</option><option>East Depot</option></select>${ic('down', 15)}</div>`)}${field('Units (kWh)', '<input class="inp" type="number" value="1450"/>')}${field('Month', '<input class="inp" value="September 2026"/>')}`, `<button class="btn btn-outline" data-act="mclose">Cancel</button><button class="btn btn-primary" data-act="logelec2">Save</button>`);
ACT.logelec2 = () => { closeModal(); toast('Electricity usage logged: 1.2 t CO\u2082'); };
ACT.settarget2 = () => { closeModal(); toast('Target saved: 20% reduction by Mar 2027'); };
ACT.calcem = () => openModal('Calculate Emissions', `<div class="g mt12" style="grid-template-columns:1fr 1fr">${field('Diesel (L)', '<input class="inp" type="number" id="ce1" value="8420"/>')}${field('Electricity (kWh)', '<input class="inp" type="number" id="ce2" value="1450"/>')}</div><div class="sbox mt12" id="ceout"></div>`, `<button class="btn btn-primary" data-act="calcem2">Calculate</button>`);
ACT.calcem2 = () => { const d = Number(document.getElementById('ce1').value), e = Number(document.getElementById('ce2').value); const t = d * 2.68 / 1000 + e * 0.82 / 1000; document.getElementById('ceout').innerHTML = `<div class="b fs18">${t.toFixed(1)} t CO₂</div><div class="fs12 mut">Diesel ${(d * 2.68 / 1000).toFixed(1)} t + Electricity ${(e * .82 / 1000).toFixed(1)} t (India grid factor 0.82 kg/kWh)</div>`; };
ACT.settarget = () => openModal('Set Reduction Target', `${field('Target reduction', '<div class="row"><input class="inp" type="number" value="20" style="width:100px"/> <span>% by</span><input class="inp" type="date" value="2027-03-31" style="width:180px"/></div>')}${field('Focus', `<div class="sel" style="width:100%"><select><option>Shift 5 buses to CNG</option><option>Route optimisation</option><option>Idle-time reduction</option></select>${ic('down', 15)}</div>`)}`, `<button class="btn btn-outline" data-act="mclose">Cancel</button><button class="btn btn-primary" data-act="settarget2">Save Target</button>`);

/* ---------------- Reports, audit, settings ---------------- */
page('admin/reports', {
  title: 'Reports', render: r => {
    const sec = r.params.s || 'fleet-reports';
    const groups = { 'fleet-reports': ['Fleet Utilisation', 'Vehicle KM Summary', 'Fuel Efficiency by Vehicle', 'Idle Time Report'], 'trip-reports': ['Daily Trip Summary', 'On-Time Performance', 'Route Deviation Log', 'Stop-wise Delay Analysis'], 'student-reports': ['Boarding Attendance', 'Students Without Route', 'Absentee Trends', 'Parent App Adoption'], 'finance-reports': ['Fee Collection', 'Outstanding Dues', 'Expense Ledger', 'Vendor Payments'], 'safety-reports': ['Incident Register', 'SOS Response Times', 'Driver Compliance', 'Vehicle Compliance'], 'scheduled-reports': ['Weekly Ops Digest (Mon 8 AM)', 'Monthly Finance Pack (1st, 9 AM)', 'Daily Safety Summary (7 PM)'] };
    return `${adminHead('Reports', 'Generate, download and schedule reports across fleet, trips, students, finance and safety.', `<button class="btn btn-primary" data-act="genreport">${ic('plus', 16)}New Report</button>`)}
    <div class="card" style="margin-bottom:12px"><div class="tabs big" style="padding:0 10px;border:0">${Object.keys(groups).map(k => `<button class="tab ${sec === k ? 'on' : ''}" data-go="#/admin/reports?s=${k}">${k.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase())}</button>`).join('')}</div></div>
    <div class="g rgrid" style="grid-template-columns:repeat(4,minmax(0,1fr))">${groups[sec].map((g, i) => `<div class="card" style="padding:16px">${tile(['barsc', 'filechart', 'pie', 'file'][i % 4], '#2563eb', '#eaf1ff', 46, 24, 12)}<div class="b fs15 mt12">${g}</div><div class="fs12 mut mt4">Last generated ${['today, 08:00 AM', 'yesterday', '24 Sep 2026', '20 Sep 2026'][i % 4]}</div><div class="row mt12" style="gap:8px"><button class="btn btn-primary btn-sm" data-act="susreport" data-n="${g}">${ic('download', 14)}Generate</button><button class="btn btn-outline btn-sm" data-act="toast" data-msg="${g} scheduled weekly">${ic('cal', 14)}Schedule</button></div></div>`).join('')}</div>`;
  },
});
page('admin/audit', {
  title: 'Audit Trail', render: () => {
    const q = ((UI.aud || {}).q || '').toLowerCase();
    const seed = [['10:24 AM', '26 Sep 2026', 'Super Admin', 'Login', 'Signed in from Chrome, Gandhinagar'], ['10:12 AM', '26 Sep 2026', 'Transport Coordinator', 'Route updated', 'R-03 stop order changed'], ['09:40 AM', '26 Sep 2026', 'Finance Officer', 'Fee collected', '₹24,000 from Aarav Sharma via UPI'], ['09:15 AM', '26 Sep 2026', 'Maintenance Manager', 'Work order created', 'WO-2026-014 for GJ01EF9012'], ['08:12 AM', '26 Sep 2026', 'System', 'Delay alert', 'GJ01AB1234 delayed by 45 minutes'], ['07:32 AM', '26 Sep 2026', 'System', 'SOS received', 'Diya Patel (R-05)'], ['06:45 AM', '26 Sep 2026', 'Ramesh Patel', 'Attendance', 'Driver checked in with face + GPS']];
    const rows = [...A().audit.map(a => [a.t, a.d, a.user, a.action, a.detail]), ...seed].filter(r => !q || r.join(' ').toLowerCase().includes(q));
    return `${adminHead('Audit Trail', 'Every change made in the workspace, who made it and when.', `<button class="btn btn-outline" data-act="exportcsv" data-what="Audit trail">${ic('export', 16)}Export</button>`)}<div class="filters">${searchBox('u:aud.q', 'Search user, action or details...', (UI.aud || {}).q)}${sel('u:aud.u', ['All Users', 'Super Admin', 'Maintenance Manager', 'System'], (UI.aud || {}).u || 'All Users', 'data-norefresh')}<span class="sp"></span>${dateSel('audd')}</div><div class="card"><table class="tbl"><thead><tr><th>Time</th><th>Date</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody>${rows.map((r, i) => `<tr${i < A().audit.length ? ' style="background:#f6fbf7"' : ''}><td class="nowrap">${r[0]}</td><td class="nowrap">${r[1]}</td><td><span class="row">${av(r[2], 26)}${esc(r[2])}</span></td><td class="m5">${esc(r[3])}</td><td class="mut">${esc(r[4])}</td></tr>`).join('') || emptyRow(5)}</tbody></table></div>${A().audit.length ? `<div class="fs12 mut mt8">${A().audit.length} change(s) made in this demo session are highlighted.</div>` : ''}`;
  },
});
page('admin/settings', { title: 'Settings', render: () => settingsPage() });

