    const map = { overview: 'dashboard', 'preventive-maintenance': 'schedule', 'service-requests': 'vehicles', 'repair-work-orders': 'workorders', inspections: 'inspections', 'spare-parts-inventory': 'parts', 'vendors-garages': 'parts', documents: 'documents', 'maintenance-reports': 'reports' };
